uniform vec2 iResolution;
uniform float iTime;
uniform shader composable;
uniform float uAnimationProgress; // min: 0.0, max: 1.0, default: 0.0, 전체 애니메이션 진행도 (0~1)
uniform float uCircle1MinRadius; // min: 0.0, max: 1.0, default: 0.1, 첫 번째 원 최소 반지름 (음수: 역방향)
uniform float uCircle2MinRadius; // min: 0.0, max: 1.0, default: 0.0, 두 번째 원 최소 반지름 (음수: 역방향)
uniform float uCircle3MinRadius; // min: 0.0, max: 1.0, default: 0.1, 세 번째 원 최소 반지름 (음수: 역방향)
uniform float uCircle1MaxRadius; // min: 0.05, max: 2.0, default: 0.5, 첫 번째 원 최대 반지름
uniform float uCircle2MaxRadius; // min: 0.05, max: 2.0, default: 0.5, 두 번째 원 최대 반지름
uniform float uCircle3MaxRadius; // min: 0.05, max: 2.0, default: 1.5, 세 번째 원 최대 반지름
uniform vec2 uCircle1Pos; // min: [0.0, 0.0], max: [1.0, 1.0], default: [0.2, 0.3], 첫 번째 원 기본 위치
uniform vec2 uCircle2Pos; // min: [0.0, 0.0], max: [1.0, 1.0], default: [0.8, 0.2], 두 번째 원 기본 위치
uniform vec2 uCircle3Pos; // min: [0.0, 0.0], max: [1.0, 1.0], default: [0.5, 0.9], 세 번째 원 기본 위치
uniform float uRandomOffset; // min: 0.0, max: 1.0, default: 0.1, 원들의 위치 랜덤 오프셋 시드값
uniform float uSmoothness; // min: 0.0, max: 0.5, default: 0.5, 원의 가장자리 부드러움
uniform float uCircle1StartDelay; // min: 0.0, max: 5.0, default: 0.0, 첫 번째 원 시작 지연시간 (초)
uniform float uCircle2StartDelay; // min: 0.0, max: 5.0, default: 2.6, 두 번째 원 시작 지연시간 (초)
uniform float uCircle3StartDelay; // min: 0.0, max: 5.0, default: 2.4, 세 번째 원 시작 지연시간 (초)
uniform float uCircle1Duration; // min: 0.1, max: 10.0, default: 8.6, 첫 번째 원 애니메이션 지속시간 (초)
uniform float uCircle2Duration; // min: 0.1, max: 10.0, default: 9.0, 두 번째 원 애니메이션 지속시간 (초)
uniform float uCircle3Duration; // min: 0.1, max: 10.0, default: 10.0, 세 번째 원 애니메이션 지속시간 (초)
uniform float uHideImage; // min: 0.0, max: 1.0, default: 0.0, 0: 이미지 마스킹
float random(float seed) {
    return fract(sin(seed * 12.9898 + 4.1414) * 43758.5453);
}

float random2(float seed) {
    return fract(sin(seed * 78.233 + 15.789) * 31416.9265);
}

vec2 getRandomOffset(float seed, float circleIndex) {
    float baseSeed = seed * 1000.0;
    float seedX = baseSeed + circleIndex * 123.456 + 789.012;
    float seedY = baseSeed + circleIndex * 456.789 + 321.654;

    float r1 = random(seedX) * 2.0 - 1.0;
    float r2 = random2(seedY) * 2.0 - 1.0;

    return vec2(r1, r2) * 0.3;
}

float easeOut(float t) {
    t = clamp(t, 0.0, 1.0);
    return 1.0 - (1.0 - t)*(1.0 - t);
}

vec4 main(vec2 fragCoord)
{

    // Y 방향 반전
    vec2 uv = fragCoord / iResolution.xy;

    vec4 texColor = composable.eval(uv * iResolution.xy);

    float totalLength = max(max(uCircle1StartDelay + uCircle1Duration, uCircle2StartDelay + uCircle2Duration), uCircle3StartDelay + uCircle3Duration);

    float circle1Start = uCircle1StartDelay / totalLength;
    float circle1End   = (uCircle1StartDelay + uCircle1Duration) / totalLength;
    float circle2Start = uCircle2StartDelay / totalLength;
    float circle2End   = (uCircle2StartDelay + uCircle2Duration) / totalLength;
    float circle3Start = uCircle3StartDelay / totalLength;
    float circle3End   = (uCircle3StartDelay + uCircle3Duration) / totalLength;

    float rawProgress1 = clamp((uAnimationProgress - circle1Start) / (circle1End - circle1Start), 0.0, 1.0);
    float rawProgress2 = clamp((uAnimationProgress - circle2Start) / (circle2End - circle2Start), 0.0, 1.0);
    float rawProgress3 = clamp((uAnimationProgress - circle3Start) / (circle3End - circle3Start), 0.0, 1.0);

    float progress1 = easeOut(rawProgress1);
    float progress2 = easeOut(rawProgress2);
    float progress3 = easeOut(rawProgress3);

    float EPS = 0.0001;

    float radius1 = max(mix(uCircle1MinRadius, uCircle1MaxRadius, progress1), EPS);
    float radius2 = max(mix(uCircle2MinRadius, uCircle2MaxRadius, progress2), EPS);
    float radius3 = max(mix(uCircle3MinRadius, uCircle3MaxRadius, progress3), EPS);

    vec2 randomOffset1 = getRandomOffset(uRandomOffset, 1.0);
    vec2 randomOffset2 = getRandomOffset(uRandomOffset, 2.0);
    vec2 randomOffset3 = getRandomOffset(uRandomOffset, 3.0);

    vec2 circle1Pos = clamp(uCircle1Pos + randomOffset1, vec2(0.0), vec2(1.0));
    vec2 circle2Pos = clamp(uCircle2Pos + randomOffset2, vec2(0.0), vec2(1.0));
    vec2 circle3Pos = clamp(uCircle3Pos + randomOffset3, vec2(0.0), vec2(1.0));

    float dist1 = distance(uv, circle1Pos);
    float dist2 = distance(uv, circle2Pos);
    float dist3 = distance(uv, circle3Pos);

    float circle1, circle2, circle3;

    if (uSmoothness > 0.0) {
        circle1 = 1.0 - smoothstep(radius1 - uSmoothness, radius1 + uSmoothness, dist1);
        circle2 = 1.0 - smoothstep(radius2 - uSmoothness, radius2 + uSmoothness, dist2);
        circle3 = 1.0 - smoothstep(radius3 - uSmoothness, radius3 + uSmoothness, dist3);
    } else {
        circle1 = step(dist1, radius1);
        circle2 = step(dist2, radius2);
        circle3 = step(dist3, radius3);
    }

    circle1 *= step(0.01, rawProgress1);
    circle2 *= step(0.01, rawProgress2);
    circle3 *= step(0.01, rawProgress3);

    float finalMask = 1.0 - (1.0 - circle1) * (1.0 - circle2) * (1.0 - circle3);

    finalMask *= uAnimationProgress;

    if (uHideImage < 0.5) {
        vec3 premultipliedRGB = texColor.rgb * finalMask;
        return vec4(premultipliedRGB, finalMask);
    } else {
        float invertedMask = 1.0 - finalMask;
        return vec4(vec3(invertedMask), 1.0);
    }

}

